package org.apache.camel.component.infinispan.remote.protostream;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.ObjectInputFilter;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;

import org.apache.camel.support.DefaultExchangeHolder;
import org.apache.camel.util.ClassLoadingAwareObjectInputStream;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Utilities for {@link DefaultExchangeHolder} and the Infinispan Protostream marshaller.
 */
final class DefaultExchangeHolderUtils {

    /**
     * Default deserialization filter that restricts which classes can be deserialized. Allows standard Java types and
     * Apache Camel types. Can be overridden via the JVM system property {@code jdk.serialFilter}.
     */
    static final String DEFAULT_DESERIALIZATION_FILTER = "java.**;javax.**;org.apache.camel.**;!*";

    private static final Logger LOG = LoggerFactory.getLogger(DefaultExchangeHolderUtils.class);

    private DefaultExchangeHolderUtils() {
        // Utility class
    }

    static byte[] serialize(DefaultExchangeHolder holder) {
        try (ByteArrayOutputStream baos = new ByteArrayOutputStream(); ObjectOutputStream oos = new ObjectOutputStream(baos)) {
            oos.writeObject(holder);
            return baos.toByteArray();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    static DefaultExchangeHolder deserialize(byte[] bytes) {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(bytes);
             ObjectInputStream ois = new ClassLoadingAwareObjectInputStream(bais)) {
            ObjectInputFilter jvmFilter = ObjectInputFilter.Config.getSerialFilter();
            if (jvmFilter != null) {
                ois.setObjectInputFilter(jvmFilter);
            } else {
                LOG.debug("No JVM-wide deserialization filter set, applying default Camel filter: {}",
                        DEFAULT_DESERIALIZATION_FILTER);
                ois.setObjectInputFilter(ObjectInputFilter.Config.createFilter(DEFAULT_DESERIALIZATION_FILTER));
            }
            return (DefaultExchangeHolder) ois.readObject();
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException(e);
        }
    }
}

package urlx

import (
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestIsSameSite(t *testing.T) {
	tests := []struct {
		url  string
		want bool
	}{
		{url: "//github.com", want: false},
		{url: "http://github.com", want: false},
		{url: "https://github.com", want: false},
		{url: "", want: false},
		{url: "javascript:alert(1)", want: false},

		{url: "/", want: true},
		{url: "/admin", want: true},
		{url: "/user/repo", want: true},
		{url: "/user/repo?key=value", want: true},
		{url: "/user/repo#anchor", want: true},

		// Backslash bypasses: browsers normalize `\` to `/` on Location headers.
		{url: "/\\github.com", want: false},
		{url: "/a/../\\example.com", want: false},
		{url: "/\\\\example.com", want: false},
		// Percent-encoded backslashes decode after c.Query, so they're caught too.
		{url: "/%5Cexample.com", want: false},
		{url: "/%5cexample.com", want: false},
		{url: "/a/../%5Cexample.com", want: false},

		// Whitespace bypasses: browsers strip tab/CR/LF before resolving.
		{url: "/\t/example.com", want: false},
		{url: "/\n/example.com", want: false},
		{url: "/\r/example.com", want: false},
		{url: "/\texample.com", want: true},
	}

	for _, test := range tests {
		t.Run(test.url, func(t *testing.T) {
			assert.Equal(t, test.want, IsSameSite(test.url))
		})
	}
}

package logic

import (
	"errors"
	"time"

	"github.com/golang-jwt/jwt/v4"
	"github.com/gravitl/netmaker/models"
	"github.com/gravitl/netmaker/servercfg"
)

var jwtSecretKey = []byte("(BytesOverTheWire)")

// CreateJWT func will used to create the JWT while signing in and signing out
func CreateJWT(uuid string, macAddress string, network string) (response string, err error) {
	expirationTime := time.Now().Add(5 * time.Minute)
	claims := &models.Claims{
		ID:         uuid,
		Network:    network,
		MacAddress: macAddress,
		StandardClaims: jwt.StandardClaims{
			ExpiresAt: expirationTime.Unix(),
		},
	}

	token := jwt.NewWithClaims(jwt.SigningMethodHS256, claims)
	tokenString, err := token.SignedString(jwtSecretKey)
	if err == nil {
		return tokenString, nil
	}
	return "", err
}

// CreateUserJWT - creates a user jwt token
func CreateUserJWT(username string, networks []string, isadmin bool) (response string, err error) {
	expirationTime := time.Now().Add(60 * 12 * time.Minute)
	claims := &models.UserClaims{
		UserName: username,
		Networks: networks,
		IsAdmin:  isadmin,
		StandardClaims: jwt.StandardClaims{
			ExpiresAt: expirationTime.Unix(),
		},
	}

	token := jwt.NewWithClaims(jwt.SigningMethodHS256, claims)
	tokenString, err := token.SignedString(jwtSecretKey)
	if err == nil {
		return tokenString, nil
	}
	return "", err
}

// VerifyToken func will used to Verify the JWT Token while using APIS
func VerifyUserToken(tokenString string) (username string, networks []string, isadmin bool, err error) {
	claims := &models.UserClaims{}

	if tokenString == servercfg.GetMasterKey() {
		return "masteradministrator", nil, true, nil
	}

	token, err := jwt.ParseWithClaims(tokenString, claims, func(token *jwt.Token) (interface{}, error) {
		return jwtSecretKey, nil
	})

	if token != nil && token.Valid {
		// check that user exists
		if user, err := GetUser(claims.UserName); user.UserName != "" && err == nil {
			return claims.UserName, claims.Networks, claims.IsAdmin, nil
		}
		err = errors.New("user does not exist")
	}
	return "", nil, false, err
}

// VerifyToken - gRPC [nodes] Only
func VerifyToken(tokenString string) (nodeID string, mac string, network string, err error) {
	claims := &models.Claims{}

	//this may be a stupid way of serving up a master key
	//TODO: look into a different method. Encryption?
	if tokenString == servercfg.GetMasterKey() {
		return "mastermac", "", "", nil
	}

	token, err := jwt.ParseWithClaims(tokenString, claims, func(token *jwt.Token) (interface{}, error) {
		return jwtSecretKey, nil
	})

	if token != nil {
		return claims.ID, claims.MacAddress, claims.Network, nil
	}
	return "", "", "", err
}

package main

import (
	"bytes"
	"encoding/gob"
	"net/http"

	"github.com/gin-gonic/gin"
)

// SessionState 是从缓存/客户端恢复的会话聚合状态，
// 与原 Java 侧从远端缓存读取后直接反序列化的结构等价。
type SessionState struct {
	UserID   string
	Roles    []string
	Payload  map[string]interface{}
}

func restoreSession(c *gin.Context) {

	body, err := c.GetRawData()
	if err != nil {
		c.String(http.StatusBadRequest, "bad body")
		return
	}

	var state SessionState

	dec := gob.NewDecoder(bytes.NewReader(body))
	if err := dec.Decode(&state); err != nil {
		c.String(http.StatusInternalServerError, "decode failed")
		return
	}

	c.JSON(http.StatusOK, gin.H{"user": state.UserID, "roles": state.Roles})
}

func main() {
	r := gin.Default()
	r.POST("/session/restore", restoreSession)
	r.Run(":8080")
}
